test_that("report_selection writes an HTML report and a CSV file", {
  skip_if_not_installed("rmarkdown")
  skip_if_not(rmarkdown::pandoc_available())
  pd <- suppressMessages(prepare_input(
    salmonella_strains, col_select = c("CONTEXTE", "REGION", "SECTEUR"),
    id = "IDENTIFIANT"
  ))
  res <- select_strains(pd, n_max = 10, seed = 1)
  file <- file.path(tempdir(), "report_test.html")
  suppressMessages(report_selection(res, file = file, data = salmonella_strains,
                                    id = "IDENTIFIANT"))
  expect_true(file.exists(file))
  expect_true(file.exists(file.path(tempdir(), "report_test.csv")))
  html <- paste(readLines(file, warn = FALSE), collapse = "\n")
  expect_match(html, "Selection of strains to sequence")
  expect_match(html, res$selected[1])
  expect_error(report_selection(list()), "select_strains")
})
